const { setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.localStorage = null;
    this.todos = [];
    this.filter = 'all';
  }

  async setupWindow(html) {
    const win = new Window({ url: 'http://localhost' });
    win.document.write(html || this.getDefaultHtml());
    this.window = win;
    this.document = win.document;
    this.localStorage = win.localStorage;
    return win;
  }

  getDefaultHtml() {
    return `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>TodoMVC</title></head>
<body>
<section class="todoapp">
  <header class="header">
    <h1>todos</h1>
    <input class="new-todo" placeholder="What needs to be done?" autofocus>
  </header>
  <section class="main" style="display:none">
    <input id="toggle-all" class="toggle-all" type="checkbox">
    <label for="toggle-all">Mark all as complete</label>
    <ul class="todo-list"></ul>
  </section>
  <footer class="footer" style="display:none">
    <span class="todo-count"><strong>0</strong> item left</span>
    <ul class="filters">
      <li><a class="selected" href="#/">All</a></li>
      <li><a href="#/active">Active</a></li>
      <li><a href="#/completed">Completed</a></li>
    </ul>
    <button class="clear-completed">Clear completed</button>
  </footer>
</section>
<script>
${this.getAppJs()}
</script>
</body>
</html>`;
  }

  getAppJs() {
    // Inline app JS that will be loaded into the window
    return `
(function() {
  var STORAGE_KEY = 'todos-vanillajs';
  var app = {
    todos: [],
    filter: 'all',

    init: function() {
      this.todos = this.loadTodos();
      this.bindEvents();
      this.render();
    },

    loadTodos: function() {
      try {
        var stored = localStorage.getItem(STORAGE_KEY);
        return stored ? JSON.parse(stored) : [];
      } catch(e) {
        return [];
      }
    },

    saveTodos: function() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
    },

    bindEvents: function() {
      var self = this;
      var newTodo = document.querySelector('.new-todo');
      newTodo.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
          self.addTodo(newTodo.value);
        }
      });

      var toggleAll = document.getElementById('toggle-all');
      toggleAll.addEventListener('change', function() {
        self.toggleAll(this.checked);
      });
      document.querySelector('.clear-completed').addEventListener('click', function() {
        self.clearCompleted();
      });
      var todoList = document.querySelector('.todo-list');
      todoList.addEventListener('click', function(e) {
        var target = e.target;
        if (target.classList.contains('toggle')) {
          var li = target.closest('li');
          if (li) {
            var index = Array.prototype.indexOf.call(todoList.children, li);
            self.toggleTodo(index);
          }
        }
        if (target.classList.contains('destroy')) {
          var li = target.closest('li');
          if (li) {
            var index = Array.prototype.indexOf.call(todoList.children, li);
            self.destroyTodo(index);
          }
        }
      });
      todoList.addEventListener('dblclick', function(e) {
        var label = e.target.closest('label');
        if (label) {
          var li = label.closest('li');
          if (li) {
            var index = Array.prototype.indexOf.call(todoList.children, li);
            self.editTodo(index, li);
          }
        }
      });
      todoList.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
          var editInput = e.target.closest('.edit');
          if (editInput) {
            var li = editInput.closest('li');
            if (li) {
              var index = Array.prototype.indexOf.call(todoList.children, li);
              self.commitEdit(index, editInput.value);
            }
          }
        }
      });
      todoList.addEventListener('blur', function(e) {
        var editInput = e.target.closest('.edit');
        if (editInput) {
          var li = editInput.closest('li');
          if (li) {
            var index = Array.prototype.indexOf.call(todoList.children, li);
            self.commitEdit(index, editInput.value);
          }
        }
      }, true);
      todoList.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
          var editInput = e.target.closest('.edit');
          if (editInput) {
            var li = editInput.closest('li');
            if (li) {
              self.cancelEdit(li);
            }
          }
        }
      });
      window.addEventListener('hashchange', function() {
        self.route();
      });
    },

    addTodo: function(value) {
      var title = value.trim();
      if (!title) return;
      this.todos.push({
        id: Date.now().toString(36),
        title: title,
        completed: false
      });
      this.saveTodos();
      this.render();
      document.querySelector('.new-todo').value = '';
    },

    toggleTodo: function(index) {
      if (index >= 0 && index < this.todos.length) {
        this.todos[index].completed = !this.todos[index].completed;
        this.saveTodos();
        this.render();
      }
    },

    toggleAll: function(checked) {
      this.todos.forEach(function(t) { t.completed = checked; });
      this.saveTodos();
      this.render();
    },

    destroyTodo: function(index) {
      if (index >= 0 && index < this.todos.length) {
        this.todos.splice(index, 1);
        this.saveTodos();
        this.render();
      }
    },

    clearCompleted: function() {
      this.todos = this.todos.filter(function(t) { return !t.completed; });
      this.saveTodos();
      this.render();
    },

    editTodo: function(index, li) {
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      if (editInput) {
        editInput.value = this.todos[index].title;
        editInput.focus();
      }
    },

    commitEdit: function(index, value) {
      var title = value.trim();
      if (!title) {
        this.destroyTodo(index);
      } else {
        this.todos[index].title = title;
        this.saveTodos();
        this.render();
      }
    },

    cancelEdit: function(li) {
      li.classList.remove('editing');
    },

    route: function() {
      var hash = window.location.hash || '#/';
      if (hash === '#/active') this.filter = 'active';
      else if (hash === '#/completed') this.filter = 'completed';
      else this.filter = 'all';
      this.render();
    },

    getFilteredTodos: function() {
      var self = this;
      if (this.filter === 'active') {
        return this.todos.filter(function(t) { return !t.completed; });
      } else if (this.filter === 'completed') {
        return this.todos.filter(function(t) { return t.completed; });
      }
      return this.todos;
    },

    render: function() {
      var todoList = document.querySelector('.todo-list');
      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var toggleAll = document.getElementById('toggle-all');
      var todoCount = document.querySelector('.todo-count');
      var clearCompleted = document.querySelector('.clear-completed');

      todoList.innerHTML = '';

      var filtered = this.getFilteredTodos();
      var activeCount = this.todos.filter(function(t) { return !t.completed; }).length;
      var completedCount = this.todos.length - activeCount;

      if (this.todos.length === 0) {
        main.style.display = 'none';
        footer.style.display = 'none';
      } else {
        main.style.display = 'block';
        footer.style.display = 'block';
      }

      var self = this;
      filtered.forEach(function(todo) {
        var li = document.createElement('li');
        if (todo.completed) li.className = 'completed';
        li.setAttribute('data-id', todo.id);
        li.innerHTML = '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + self.escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + self.escapeHtml(todo.title) + '">';
        todoList.appendChild(li);
      });

      if (self.todos.length > 0) {
        toggleAll.checked = activeCount === 0;
      }

      var count = activeCount;
      todoCount.innerHTML = '<strong>' + count + '</strong> ' + (count === 1 ? 'item' : 'items') + ' left';

      if (completedCount === 0) {
        clearCompleted.style.display = 'none';
      } else {
        clearCompleted.style.display = 'block';
      }

      var filterLinks = document.querySelectorAll('.filters a');
      filterLinks.forEach(function(a) { a.classList.remove('selected'); });
      var selectedLink = document.querySelector('.filters a[href="#/' + (self.filter === 'all' ? '' : self.filter) + '"]');
      if (selectedLink) selectedLink.classList.add('selected');
    },

    escapeHtml: function(text) {
      var div = document.createElement('div');
      div.appendChild(document.createTextNode(text));
      return div.innerHTML;
    }
  };

  app.init();
  window.__app = app;
})();
`;
  }
}

setWorldConstructor(TodoWorld);

const { Given, When, Then, Before } = require('@cucumber/cucumber');
const { expect } = require('@cucumber/cucumber').assert? require('assert') : require('assert');

// Helper: wait a tick for DOM rendering
function wait() {
  return new Promise(resolve => setTimeout(resolve, 10));
}

// Helper: find todo by title
function findTodoItem(world, title) {
  const items = world.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) return items[i];
  }
  return null;
}

// Helper: get all todo items
function getAllTodoItems(world) {
  return world.document.querySelectorAll('.todo-list li');
}

// Helper: get todo item index
function getTodoIndex(world, title) {
  const items = world.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) return i;
  }
  return -1;
}

Before(async function () {
  await this.setupWindow();
  return wait();
});

Given('the app is loaded fresh', async function () {
  await this.setupWindow();
  return wait();
});

Given('the app has loaded', async function () {
  await this.setupWindow();
  return wait();
});

Given('the app is at the default route {string}', async function (route) {
  this.window.location.hash = route.replace('#/', '') || '';
  this.window.__app.route();
  return wait();
});

Given('that localStorage contains a saved todo with title {string} that is not completed', async function (title) {
  await this.setupWindow();
  const todos = [{ id: 'test1', title: title, completed: false }];
  this.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));
  return wait();
});

Given('a todo with title {string} exists', async function (title) {
  const app = this.window.__app;
  app.addTodo(title);
  return wait();
});

When('the user types {string} into the new-todo input', async function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  return wait();
});

When('the user types {string} into the edit input', async function (text) {
  const editInput = this.document.querySelector('.edit');
  if (editInput) editInput.value = text;
  return wait();
});

When('presses Enter', async function () {
  const active = this.document.activeElement;
  if (active) {
    active.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', bubbles: true }));
  }
  return wait();
});

When('presses Escape', async function () {
  const active = this.document.activeElement;
  if (active) {
    active.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  }
  return wait();
});

When('the user adds {int} active todo with title {string}', async function (count, title) {
  const app = this.window.__app;
  app.addTodo(title);
  return wait();
});

When('the user adds {int} active todos with titles {string} and {string}', async function (count, title1, title2) {
  const app = this.window.__app;
  app.addTodo(title1);
  app.addTodo(title2);
  return wait();
});

When('the user adds {int} active todos with titles {string}, {string}, and {string}', async function (count, title1, title2, title3) {
  const app = this.window.__app;
  app.addTodo(title1);
  app.addTodo(title2);
  app.addTodo(title3);
  return wait();
});

When('the user marks {string} as completed', async function (title) {
  const app = this.window.__app;
  const index = getTodoIndex(this, title);
  if (index >= 0) app.toggleTodo(index);
  return wait();
});

When('the user clicks the toggle checkbox for {string}', async function (title) {
  const app = this.window.__app;
  const index = getTodoIndex(this, title);
  if (index >= 0) app.toggleTodo(index);
  return wait();
});

When('the user clicks the toggle-all checkbox', async function () {
  const toggleAll = this.document.getElementById('toggle-all');
  toggleAll.checked = !toggleAll.checked;
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  return wait();
});

When('the user clicks the clear-completed button', async function () {
  const app = this.window.__app;
  app.clearCompleted();
  return wait();
});

When('the user double-clicks the label for {string}', async function (title) {
  const item = findTodoItem(this, title);
  if (item) {
    const label = item.querySelector('label');
    if (label) {
      label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
    }
  }
  return wait();
});

When('the edit input loses focus', async function () {
  const editInput = this.document.querySelector('.edit');
  if (editInput) {
    editInput.dispatchEvent(new this.window.FocusEvent('blur', { bubbles: true }));
  }
  return wait();
});

When('the user clears the edit input', async function () {
  const editInput = this.document.querySelector('.edit');
  if (editInput) editInput.value = '';
  return wait();
});

When('the page is reloaded', async function () {
  const stored = this.localStorage.getItem('todos-vanillajs');
  await this.setupWindow();
  if (stored) {
    this.localStorage.setItem('todos-vanillajs', stored);
  }
  this.window.__app.init();
  return wait();
});

When('the page is reloaded immediately', async function () {
  const stored = this.localStorage.getItem('todos-vanillajs');
  await this.setupWindow();
  if (stored) {
    this.localStorage.setItem('todos-vanillajs', stored);
  }
  this.window.__app.init();
  return wait();
});

When('the user navigates to {string}', async function (hash) {
  this.window.location.hash = hash.replace('#/', '') || '';
  this.window.__app.route();
  return wait();
});

Then('the new-todo input field is visible', async function () {
  const input = this.document.querySelector('.new-todo');
  expect(input).not.toBeNull();
  expect(input.offsetParent).not.toBeNull();
});

Then('the main section is not visible', async function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).toBe('none');
});

Then('the footer is not visible', async function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).toBe('none');
});

Then('the todo list contains {int} item', async function (count) {
  const items = getAllTodoItems(this);
  expect(items.length).toBe(count);
});

Then('the new-todo input is cleared', async function () {
  const input = this.document.querySelector('.new-todo');
  expect(input.value).toBe('');
});

Then('the main section is visible', async function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).not.toBe('none');
});

Then('the footer is visible', async function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).not.toBe('none');
});

Then('the todo list is empty', async function () {
  const items = getAllTodoItems(this);
  expect(items.length).toBe(0);
});

Then('the todo list contains {int} item with title {string}', async function (count, title) {
  const items = getAllTodoItems(this);
  expect(items.length).toBe(count);
  if (count > 0) {
    const label = items[0].querySelector('label');
    expect(label.textContent).toBe(title);
  }
});

Then('the todo-count shows {string}', async function (expected) {
  const countEl = this.document.querySelector('.todo-count');
  expect(countEl.textContent.trim()).toBe(expected);
});

Then('the clear-completed button is visible', async function () {
  const btn = this.document.querySelector('.clear-completed');
  expect(btn.style.display).not.toBe('none');
});

Then('the clear-completed button is not visible', async function () {
  const btn = this.document.querySelector('.clear-completed');
  expect(btn.style.display).toBe('none');
});

Then('the todo list does not contain {string}', async function (title) {
  const item = findTodoItem(this, title);
  expect(item).toBeNull();
});

Then('the todo item {string} has class {string}', async function (title, className) {
  const item = findTodoItem(this, title);
  expect(item).not.toBeNull();
  expect(item.classList.contains(className)).toBe(true);
});

Then('the todo item {string} shows as checked', async function (title) {
  const item = findTodoItem(this, title);
  expect(item).not.toBeNull();
  const checkbox = item.querySelector('.toggle');
  expect(checkbox).not.toBeNull();
  expect(checkbox.checked).toBe(true);
});

Then('every todo item has class {string}', async function (className) {
  const items = getAllTodoItems(this);
  for (let i = 0; i < items.length; i++) {
    expect(items[i].classList.contains(className)).toBe(true);
  }
});

Then('the toggle-all checkbox is checked', async function () {
  const toggleAll = this.document.getElementById('toggle-all');
  expect(toggleAll.checked).toBe(true);
});

Then('the toggle-all checkbox is not checked', async function () {
  const toggleAll = this.document.getElementById('toggle-all');
  expect(toggleAll.checked).toBe(false);
});

Then('the edit input is visible and focused', async function () {
  const editInput = this.document.querySelector('.edit');
  expect(editInput).not.toBeNull();
  expect(this.document.activeElement === editInput).toBe(true);
});

Then('the edit input contains {string}', async function (value) {
  const editInput = this.document.querySelector('.edit');
  expect(editInput.value).toBe(value);
});

Then('the todo item {string} is updated to {string}', async function (oldTitle, newTitle) {
  const item = findTodoItem(this, newTitle);
  expect(item).not.toBeNull();
  const label = item.querySelector('label');
  expect(label.textContent).toBe(newTitle);
});

Then('the todo item {string} does not have class {string}', async function (title, className) {
  const item = findTodoItem(this, title);
  expect(item).not.toBeNull();
  expect(item.classList.contains(className)).toBe(false);
});

Then('the todo item title remains {string}', async function (title) {
  const item = findTodoItem(this, title);
  expect(item).not.toBeNull();
  const label = item.querySelector('label');
  expect(label.textContent).toBe(title);
});

Then('localStorage contains a key matching {string}', async function (pattern) {
  const keys = Object.keys(this.localStorage);
  const regex = new RegExp(pattern);
  const match = keys.some(k => regex.test(k));
  expect(match).toBe(true);
});

Then('the stored value includes an item with title {string}', async function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  const match = data.some(t => t.title === title);
  expect(match).toBe(true);
});

Then('the stored value includes an item with id', async function () {
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  const match = data.some(t => t.id !== undefined);
  expect(match).toBe(true);
});

Then('the stored item with title {string} has completed set to false', async function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  const item = data.find(t => t.title === title);
  expect(item).not.toBeUndefined();
  expect(item.completed).toBe(false);
});

Then('the stored item with title {string} has completed set to true', async function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  const item = data.find(t => t.title === title);
  expect(item).not.toBeUndefined();
  expect(item.completed).toBe(true);
});

Then('the stored todo has keys {string}, {string}, and {string}', async function (key1, key2, key3) {
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  const item = data[0];
  expect(item).not.toBeUndefined();
  expect(Object.keys(item).sort()).toEqual([key1, key2, key3].sort());
});

Then('the todo list shows {int} items', async function (count) {
  const items = getAllTodoItems(this);
  expect(items.length).toBe(count);
});

Then('the {string} filter link has class {string}', async function (filter, className) {
  let href;
  if (filter === 'All') href = '#/';
  else if (filter === 'Active') href = '#/active';
  else if (filter === 'Completed') href = '#/completed';
  const link = this.document.querySelector(`.filters a[href="${href}"]`);
  expect(link).not.toBeNull();
  expect(link.classList.contains(className)).toBe(true);
});

Then('the displayed items are {string} and {string}', async function (item1, item2) {
  const items = getAllTodoItems(this);
  const labels = Array.from(items).map(li => li.querySelector('label').textContent);
  expect(labels).toEqual([item1, item2]);
});

Then('the displayed items are {string}', async function (item1) {
  const items = getAllTodoItems(this);
  const labels = Array.from(items).map(li => li.querySelector('label').textContent);
  expect(labels).toEqual([item1]);
});

const common = [
  'features/**/*.feature',
  '--require features/step_definitions/**/*.js',
  '--require features/support/**/*.js',
  '--format progress',
].join(' ');

module.exports = {
  default: common,
};

