async setupWindow(html) {
  const win = new Window({ url: 'http://localhost' });
  win.document.write(html || this.getDefaultHtml());
  this.window = win;
  this.document = win.document;
  this.localStorage = win.localStorage;
  // Execute app code directly since happy-dom doesn't run inline scripts
  this.executeAppCode(win);
  return win;
}

executeAppCode(win) {
  const app = this.getAppObject(win);
  app.init();
  win.__app = app;
}

getAppObject(win) {
  var STORAGE_KEY = 'todos-vanillajs';
  var selfRef = this;
  return {
    todos: [],
    filter: 'all',
    STORAGE_KEY: STORAGE_KEY,

    init: function() {
      this.todos = this.loadTodos();
      this.bindEvents(win);
      this.render(win);
    },

    loadTodos: function() {
      try {
        var stored = win.localStorage.getItem(STORAGE_KEY);
        return stored ? JSON.parse(stored) : [];
      } catch(e) {
        return [];
      }
    },

    saveTodos: function() {
      win.localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
    },

    bindEvents: function(win) {
      var self = this;
      var doc = win.document;
      var newTodo = doc.querySelector('.new-todo');
      if (newTodo) {
        newTodo.addEventListener('keypress', function(e) {
          if (e.key === 'Enter') {
            self.addTodo(newTodo.value);
          }
        });
      }

      var toggleAll = doc.getElementById('toggle-all');
      if (toggleAll) {
        toggleAll.addEventListener('change', function() {
          self.toggleAll(this.checked);
        });
      }

      var clearBtn = doc.querySelector('.clear-completed');
      if (clearBtn) {
        clearBtn.addEventListener('click', function() {
          self.clearCompleted();
        });
      }

      var todoList = doc.querySelector('.todo-list');
      if (todoList) {
        todoList.addEventListener('click', function(e) {
          var target = e.target;
          if (target.classList.contains('toggle')) {
            var li = target.closest('li');
            if (li) {
              var index = Array.prototype.indexOf.call(todoList.children, li);
              self.toggleTodo(index);
            }
          }
          if (target.classList.contains('destroy')) {
            var li = target.closest('li');
            if (li) {
              var index = Array.prototype.indexOf.call(todoList.children, li);
              self.destroyTodo(index);
            }
          }
        });

        todoList.addEventListener('dblclick', function(e) {
          var label = e.target.closest('label');
          if (label) {
            var li = label.closest('li');
            if (li) {
              var index = Array.prototype.indexOf.call(todoList.children, li);
              self.editTodo(index, li);
            }
          }
        });

        todoList.addEventListener('keypress', function(e) {
          if (e.key === 'Enter') {
            var editInput = e.target.closest('.edit');
            if (editInput) {
              var li = editInput.closest('li');
              if (li) {
                var index = Array.prototype.indexOf.call(todoList.children, li);
                self.commitEdit(index, editInput.value);
              }
            }
          }
        });

        todoList.addEventListener('blur', function(e) {
          var editInput = e.target.closest('.edit');
          if (editInput) {
            var li = editInput.closest('li');
            if (li) {
              var index = Array.prototype.indexOf.call(todoList.children, li);
              self.commitEdit(index, editInput.value);
            }
          }
        }, true);

        todoList.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') {
            var editInput = e.target.closest('.edit');
            if (editInput) {
              var li = editInput.closest('li');
              if (li) {
                self.cancelEdit(li);
              }
            }
          }
        });
      }

      win.addEventListener('hashchange', function() {
        self.route();
      });
    },

    addTodo: function(value) {
      var title = value.trim();
      if (!title) return;
      this.todos.push({
        id: Date.now().toString(36),
        title: title,
        completed: false
      });
      this.saveTodos();
      this.render(win);
      var input = win.document.querySelector('.new-todo');
      if (input) input.value = '';
    },

    toggleTodo: function(index) {
      if (index >= 0 && index < this.todos.length) {
        this.todos[index].completed = !this.todos[index].completed;
        this.saveTodos();
        this.render(win);
      }
    },

    toggleAll: function(checked) {
      for (var i = 0; i < this.todos.length; i++) { this.todos[i].completed = checked; }
      this.saveTodos();
      this.render(win);
    },

    destroyTodo: function(index) {
      if (index >= 0 && index < this.todos.length) {
        this.todos.splice(index, 1);
        this.saveTodos();
        this.render(win);
      }
    },

    clearCompleted: function() {
      this.todos = this.todos.filter(function(t) { return !t.completed; });
      this.saveTodos();
      this.render(win);
    },

    editTodo: function(index, li) {
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      if (editInput) {
        editInput.value = this.todos[index].title;
        editInput.focus();
      }
    },

    commitEdit: function(index, value) {
      var title = value.trim();
      if (!title) {
        this.destroyTodo(index);
      } else {
        this.todos[index].title = title;
        this.saveTodos();
        this.render(win);
      }
    },

    cancelEdit: function(li) {
      li.classList.remove('editing');
    },

    route: function() {
      var hash = win.location.hash || '#/';
      if (hash === '#/active') this.filter = 'active';
      else if (hash === '#/completed') this.filter = 'completed';
      else this.filter = 'all';
      this.render(win);
    },

    getFilteredTodos: function() {
      if (this.filter === 'active') {
        return this.todos.filter(function(t) { return !t.completed; });
      } else if (this.filter === 'completed') {
        return this.todos.filter(function(t) { return t.completed; });
      }
      return this.todos;
    },

    render: function(win) {
      var doc = win.document;
      var todoList = doc.querySelector('.todo-list');
      var main = doc.querySelector('.main');
      var footer = doc.querySelector('.footer');
      var toggleAll = doc.getElementById('toggle-all');
      var todoCount = doc.querySelector('.todo-count');
      var clearCompleted = doc.querySelector('.clear-completed');

      if (!todoList) return;
      todoList.innerHTML = '';

      var filtered = this.getFilteredTodos();
      var activeCount = this.todos.filter(function(t) { return !t.completed; }).length;
      var completedCount = this.todos.length - activeCount;

      if (this.todos.length === 0) {
        if (main) main.style.display = 'none';
        if (footer) footer.style.display = 'none';
      } else {
        if (main) main.style.display = 'block';
        if (footer) footer.style.display = 'block';
      }

      for (var i = 0; i < filtered.length; i++) {
        var todo = filtered[i];
        var li = doc.createElement('li');
        if (todo.completed) li.className = 'completed';
        li.setAttribute('data-id', todo.id);
        li.innerHTML = '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + this._escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + this._escapeHtml(todo.title) + '">';
        todoList.appendChild(li);
      }

      if (toggleAll) {
        toggleAll.checked = this.todos.length > 0 && activeCount === 0;
      }

      if (todoCount) {
        var count = activeCount;
        todoCount.innerHTML = '<strong>' + count + '</strong> ' + (count === 1 ? 'item' : 'items') + ' left';
      }

      if (clearCompleted) {
        if (completedCount === 0) {
          clearCompleted.style.display = 'none';
        } else {
          clearCompleted.style.display = 'block';
        }
      }

      var filterLinks = doc.querySelectorAll('.filters a');
      for (var f = 0; f < filterLinks.length; f++) {
        filterLinks[f].classList.remove('selected');
      }
      var filterHref = this.filter === 'all' ? '#/' : '#/' + this.filter;
      var selectedLink = doc.querySelector('.filters a[href="' + filterHref + '"]');
      if (selectedLink) selectedLink.classList.add('selected');
    },

    _escapeHtml: function(text) {
      var div = win.document.createElement('div');
      div.appendChild(win.document.createTextNode(text));
      return div.innerHTML;
    }
  };
}

